import{_ as o,c as a,o as i,a5 as t}from"./chunks/framework.CUJoMJm2.js";const u=JSON.parse('{"title":"SBP Wire Format (v1)","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbp/wire-format.md","filePath":"protocols/sbp/wire-format.md","lastUpdated":1768070912000}'),d={name:"protocols/sbp/wire-format.md"};function r(s,e,c,l,n,m){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="sbp-wire-format-v1" tabindex="-1">SBP Wire Format (v1) <a class="header-anchor" href="#sbp-wire-format-v1" aria-label="Permalink to “SBP Wire Format (v1)”">​</a></h1><p>Canonical on-wire contract for <code>@sideband/protocol</code>. Applies to all transports that carry SBP frames (WS, loopback, future TCP). Values are little-endian unless stated otherwise.</p><p><strong>Note</strong>: All v1 implementations MUST support the timestamp flag bit (bit 0), even if unused. Frames with bit 0 set include an 8-byte timestamp after the frame ID.</p><h2 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to “Envelope”">​</a></h2><ul><li>Version tag: <code>sideband/1</code> (see <code>PROTOCOL_ID</code>). All frames belong to this version; negotiation happens via the handshake payload, not per-frame.</li><li><strong>Header (fixed 2 bytes)</strong>: <code>t</code> (1 byte, <code>FrameKind</code>), <code>flags</code> (1 byte). <ul><li><strong>Important</strong>: Flags are part of the frame header, <strong>not</strong> part of the FrameId.</li><li><strong>Bit 0</strong> (<code>ts</code>): timestamp present (1) or absent (0). When set, an 8-byte timestamp follows the frame header before the payload.</li><li><strong>Bits 1–7</strong>: reserved and must be zero in v1. Non-zero reserved bits close the connection.</li></ul></li><li><strong>Frame ID (<code>id</code>)</strong>: <strong>16 raw bytes (128 bits) of opaque entropy. Always present.</strong> Generated via cryptographic randomness. Used for request/response correlation and ACK linkage; auto-generated to simplify runtime logic. No padding, no string encoding, no trimming, no semantic bits. <ul><li>Decoders MUST treat FrameId as raw binary.</li><li>Decoders MUST NOT interpret any bits within FrameId.</li><li>Validation is length-only: must be exactly 16 bytes.</li></ul></li><li><strong>Optional timestamp</strong> (if <code>flags</code> bit 0 is set): 8-byte signed int (milliseconds since Unix epoch).</li><li><strong>Payload</strong>: type-specific body (below).</li></ul><h2 id="frame-kinds" tabindex="-1">Frame kinds <a class="header-anchor" href="#frame-kinds" aria-label="Permalink to “Frame kinds”">​</a></h2><ul><li>Control (<code>t=0</code>): first byte <code>c</code> (<code>ControlOp</code>), rest <code>data</code> (opaque). <ul><li>Handshake (<code>c=0</code>): <code>data</code> is UTF-8 JSON of <code>HandshakePayload</code> (see below). MUST be first frame both peers send.</li><li>Ping (<code>c=1</code>), Pong (<code>c=2</code>): no <code>data</code>. Timestamp via <code>flags</code> bit 0 is optional and recommended for keepalive latency measurement.</li><li>Close (<code>c=3</code>): optional UTF-8 reason in <code>data</code>.</li></ul></li><li>Message (<code>t=1</code>): <strong>A routable, identity-bearing unit of application data.</strong> Structure: <code>subjectLen</code> (uint32 LE) + <code>subject</code> (UTF-8, routing key) + <code>data</code> (opaque bytes). <code>frameId</code> always present for correlation; timestamp optional (via <code>flags</code> bit 0). Called &quot;Message&quot; (not &quot;Data&quot;) because each frame is a distinct, routable entity with optional acknowledgement support—semantically closer to messaging systems than byte streams. Wire keys: <code>s</code> (subject), <code>b</code> (data). <ul><li><strong>Important</strong>: <code>frameId</code> is sender-local unique and MUST NOT be reused or copied by the receiver into outbound frames. Each peer generates its own unique <code>frameId</code> for every frame it emits. For RPC correlation, see ADR-010 (uses explicit <code>cid</code> field in the envelope payload, not <code>frameId</code>).</li></ul></li><li>Ack (<code>t=2</code>): 16-byte <code>ackFrameId</code> (opaque binary, matching a prior frame&#39;s <code>frameId</code>). No payload data.</li><li>Error (<code>t=3</code>): <code>code</code> (uint16 LE <code>ErrorCode</code>) + <code>msgLen</code> (uint32 LE) + <code>message</code> (UTF-8) + optional <code>details</code> (opaque bytes). SHOULD set <code>frameId</code> to the failing frame&#39;s <code>frameId</code> when available.</li></ul><h2 id="handshake-payload-json-utf-8" tabindex="-1">Handshake payload (JSON, UTF-8) <a class="header-anchor" href="#handshake-payload-json-utf-8" aria-label="Permalink to “Handshake payload (JSON, UTF-8)”">​</a></h2><ul><li>Fields (all strings unless noted): <ul><li><code>protocol</code> (required) = <code>&quot;sideband&quot;</code></li><li><code>version</code> (required) = <code>&quot;1&quot;</code></li><li><code>peerId</code> (required) unique per peer</li><li><code>caps?</code> string[] of advertised capabilities (e.g. <code>[&quot;rpc&quot;, &quot;stream&quot;, &quot;compression:gzip&quot;]</code>)</li><li><code>metadata?</code> record of extra hints; keys MUST be namespaced (<code>&quot;tracing:...&quot;</code>, <code>&quot;vendor:...&quot;</code>).</li></ul></li><li>Rules: <ul><li>Both sides MUST send a handshake before any Message/Ack/Error frames.</li><li>On mismatch of <code>protocol</code> or <code>version</code>, respond with <code>ErrorFrame{code=UnsupportedVersion}</code> then close.</li><li>Unknown <code>caps</code>/<code>metadata</code> keys are ignored (forward-compatible).</li></ul></li></ul><h2 id="required-vs-optional-fields-v1" tabindex="-1">Required vs optional fields (v1) <a class="header-anchor" href="#required-vs-optional-fields-v1" aria-label="Permalink to “Required vs optional fields (v1)”">​</a></h2><ul><li>Required: header bytes, <code>id</code> (frameId, always present), frame-specific payload fields; handshake <code>protocol</code>, <code>version</code>, <code>peerId</code>, Message <code>subject</code>, Error <code>code</code> + <code>message</code>.</li><li>Optional: <code>ts</code>, <code>caps</code>, <code>metadata</code>, message <code>data</code>, error <code>details</code>, Close reason.</li><li>Reserved: Control ops &gt;3, future frame kinds &gt;3. For flags: bit 0 has defined semantics (timestamp); bits 1–7 are reserved and MUST be zero.</li></ul><h2 id="size-limits" tabindex="-1">Size &amp; limits <a class="header-anchor" href="#size-limits" aria-label="Permalink to “Size &amp; limits”">​</a></h2><ul><li>Recommended maximum frame size: 1 MiB; peers MAY advertise stricter caps via <code>caps</code> or out-of-band config. Frames exceeding a peer’s limit SHOULD elicit <code>ErrorFrame{code=ProtocolViolation}</code> then close.</li><li>Handshake payload SHOULD be ≤ 8 KiB.</li><li>Subjects SHOULD be ≤ 256 bytes UTF-8; longer subjects are allowed but may be rejected by implementations.</li></ul><h2 id="stream-semantics-on-the-wire" tabindex="-1">Stream semantics on the wire <a class="header-anchor" href="#stream-semantics-on-the-wire" aria-label="Permalink to “Stream semantics on the wire”">​</a></h2><ul><li>Requests/responses/events all reuse <code>Message</code> frames (<code>t=1</code>). RPC correlation is defined at the envelope layer (see RPC envelope spec): <code>cid</code> inside <code>MessageFrame.data</code> is used for request/response matching. <code>frameId</code> remains sender-local unique and is <em>not</em> reused by receivers. See ADR-010.</li><li>Acks (<code>t=2</code>) confirm receipt of the frame whose <code>frameId</code> matches <code>ackFrameId</code>; no cumulative acking.</li><li>Timestamp is advisory and not part of ordering guarantees.</li></ul><h2 id="extensibility" tabindex="-1">Extensibility <a class="header-anchor" href="#extensibility" aria-label="Permalink to “Extensibility”">​</a></h2><ul><li>Additive changes (new optional fields, new <code>ControlOp</code>, new <code>caps</code> keys) are forward-compatible for v1. New mandatory fields require a new major version.</li><li>Future alternative encodings (e.g. CBOR) must still fit this framing; <code>caps</code> SHOULD advertise <code>encoding:cbor</code> before use.</li></ul><h2 id="compatibility-matrix-v1" tabindex="-1">Compatibility matrix (v1) <a class="header-anchor" href="#compatibility-matrix-v1" aria-label="Permalink to “Compatibility matrix (v1)”">​</a></h2><ul><li>Accept frames where: <code>t</code> ∈ [0..3], reserved flag bits (1–7) are zero, required fields present, <code>frameId</code> is exactly 16 bytes. <ul><li>Bit 0 of flags can be 0 or 1 (controls timestamp presence).</li><li>Bits 1–7 MUST be zero.</li></ul></li><li>Ignore: unknown <code>caps</code>/<code>metadata</code> keys, extra bytes in Error <code>details</code>.</li><li>Reject/close: unsupported <code>protocol</code>/<code>version</code>, malformed lengths, unknown frame kind, non-zero reserved flag bits (1–7), frames before handshake, invalid <code>frameId</code> length. <ul><li><strong>Flag validation</strong>: If any bit 1–7 is set in the flags byte, send <code>ErrorFrame{code=InvalidFrame}</code> and close.</li></ul></li></ul>',19)])])}const f=o(d,[["render",r]]);export{u as __pageData,f as default};
